 v_packet jsonb := $pkt${"checkpoint":"A1Q_C3","checks":[{"code":"INTENT_FAITHFUL","statement":"El problema y el resultado deseado reformulan solo lo que dice la solicitud literal, sin cambiar su intención."},{"code":"AMBIGUITY_RETAINED","statement":"Todo lo que la solicitud no define (significados, alcance, criterios, fechas) queda como ambigüedad abierta y no se resuelve ni se asume."},{"code":"NO_INVENTION","statement":"No aparecen cifras, causas, fechas, hechos ni soluciones que la solicitud literal no contenga."}],"criterion":"Revisor ajeno al productor confirma intención y ambigüedad sin invención","decision_doc":"docs/programming-agent/ANALYSIS_C3_TIER_ACCEPTANCE_DECISION_V1.md","evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"Los clientes del marketplace deberían poder ver cuánto les ahorra negociar su deuda antes de aceptar una oferta. Hoy no lo entienden y abandonan. Que quede claro y que no se confunda con el monto de la cuota. Es urgente para el piloto.","input_sha256":"a1974eae630ef1eea450e6bd95248a73da785257de73b06e13fb727190e76987","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"items":[{"item_id":"ITEM_A","text":"{\n  \"schema_version\": \"REQUEST_CONTEXT_V1\",\n  \"request_identity\": {\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"request_kind\": \"USER_REQUEST\"\n  },\n  \"objective\": {\n    \"problem_statement\": \"Según la solicitud, los clientes del marketplace no comprenden cuánto les ahorra negociar su deuda antes de aceptar una oferta y abandonan.\",\n    \"desired_outcome\": \"Que los clientes comprendan cuánto les ahorra negociar su deuda antes de aceptar una oferta, sin confundir ese ahorro con el monto de la cuota, para el piloto.\"\n  },\n  \"target_hints\": [\n    \"clientes del marketplace\",\n    \"negociación de deuda\",\n    \"ahorro\",\n    \"oferta antes de la aceptación\",\n    \"monto de la cuota\"\n  ],\n  \"source_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"provided_facts\": [\n    {\n      \"fact_code\": \"USER_REPORTED_LACK_OF_COMPREHENSION\",\n      \"value\": \"La solicitud afirma que hoy los clientes no comprenden cuánto ahorran al negociar su deuda.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_REPORTED_ABANDONMENT\",\n      \"value\": \"La solicitud afirma que los clientes abandonan; no aporta cifras ni evidencia cuantitativa.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_STATED_PILOT_URGENCY\",\n      \"value\": \"La solicitud indica que el requerimiento es urgente para el piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    }\n  ],\n  \"constraints\": [\n    \"El ahorro debe poder conocerse antes de aceptar una oferta.\",\n    \"La información del ahorro no debe confundirse con el monto de la cuota.\",\n    \"La necesidad se declara urgente para el piloto; no se proporciona fecha límite.\"\n  ],\n  \"ambiguities\": [\n    {\n      \"code\": \"SAVINGS_MEANING_AND_BASIS\",\n      \"statement\": \"No se define qué significa 'ahorro', respecto de qué importe se compara ni cómo se determina.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"statement\": \"No se especifica en qué momento de la negociación existe una oferta que el cliente puede aceptar.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"CLIENT_CHANNEL_AND_SCOPE\",\n      \"statement\": \"No se indican los canales, pantallas o segmentos de clientes del marketplace incluidos en el piloto.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"INSTALLMENT_MEANING\",\n      \"statement\": \"No se define qué representa el monto de la cuota ni en qué situaciones corresponde distinguirlo del ahorro.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"ABANDONMENT_EVIDENCE\",\n      \"statement\": \"No se aportan mediciones, causas verificadas ni alcance del abandono mencionado.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"COMPREHENSION_CRITERION\",\n      \"statement\": \"No se define cómo se determinará que la diferencia entre ahorro y cuota resulta clara para el cliente.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"PILOT_DEADLINE\",\n      \"statement\": \"Se indica urgencia, pero no una fecha o hito preciso del piloto.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    }\n  ],\n  \"no_solution_inferred\": true\n}\n"},{"item_id":"ITEM_B","text":"{\n  \"schema_version\": \"REQUEST_CONTEXT_V1\",\n  \"request_identity\": {\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"request_kind\": \"USER_REQUEST\"\n  },\n  \"objective\": {\n    \"problem_statement\": \"Según la solicitud, los clientes del marketplace no comprenden cuánto les ahorra negociar su deuda antes de aceptar una oferta y abandonan.\",\n    \"desired_outcome\": \"Que los clientes comprendan cuánto les ahorra negociar su deuda antes de aceptar una oferta, sin confundir ese ahorro con el monto de la cuota, para el piloto.\"\n  },\n  \"target_hints\": [\n    \"clientes del marketplace\",\n    \"negociación de deuda\",\n    \"ahorro\",\n    \"oferta antes de la aceptación\",\n    \"monto de la cuota\"\n  ],\n  \"source_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"provided_facts\": [\n    {\n      \"fact_code\": \"USER_REPORTED_LACK_OF_COMPREHENSION\",\n      \"value\": \"La solicitud afirma que hoy los clientes no comprenden cuánto ahorran al negociar su deuda.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_REPORTED_ABANDONMENT\",\n      \"value\": \"Los clientes abandonan en un 40% de los casos, según la medición del piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_STATED_PILOT_URGENCY\",\n      \"value\": \"La solicitud indica que el requerimiento es urgente para el piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    }\n  ],\n  \"constraints\": [\n    \"El ahorro debe poder conocerse antes de aceptar una oferta.\",\n    \"La información del ahorro no debe confundirse con el monto de la cuota.\",\n    \"La necesidad se declara urgente para el piloto; no se proporciona fecha límite.\"\n  ],\n  \"ambiguities\": [\n    {\n      \"code\": \"SAVINGS_MEANING_AND_BASIS\",\n      \"statement\": \"No se define qué significa 'ahorro', respecto de qué importe se compara ni cómo se determina.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"statement\": \"No se especifica en qué momento de la negociación existe una oferta que el cliente puede aceptar.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"CLIENT_CHANNEL_AND_SCOPE\",\n      \"statement\": \"No se indican los canales, pantallas o segmentos de clientes del marketplace incluidos en el piloto.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"INSTALLMENT_MEANING\",\n      \"statement\": \"No se define qué representa el monto de la cuota ni en qué situaciones corresponde distinguirlo del ahorro.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"ABANDONMENT_EVIDENCE\",\n      \"statement\": \"El abandono está medido en 40% y se debe a la confusión entre ahorro y cuota.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"COMPREHENSION_CRITERION\",\n      \"statement\": \"No se define cómo se determinará que la diferencia entre ahorro y cuota resulta clara para el cliente.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"PILOT_DEADLINE\",\n      \"statement\": \"El piloto vence el 30 de noviembre.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    }\n  ],\n  \"no_solution_inferred\": true\n}\n"}],"limits":{"independent_review":false,"provider_attested":false,"real_execution_receipt":false},"packet_sha256":"039b9818988d86eb5b68ced7308cf629cee4e900713a9e80f0376a4309048996","prompt_for_gpt":"Eres un revisor independiente. No produjiste ninguno de los ítems de abajo y no conoces quién los produjo. Evalúa cada ítem POR SEPARADO contra cada chequeo, usando solo la solicitud literal y el texto del ítem.\n\nCRITERIO: Revisor ajeno al productor confirma intención y ambigüedad sin invención\n\nCHEQUEOS (evalúa cada uno, PASS o FAIL):\n- INTENT_FAITHFUL: El problema y el resultado deseado reformulan solo lo que dice la solicitud literal, sin cambiar su intención.\n- AMBIGUITY_RETAINED: Todo lo que la solicitud no define (significados, alcance, criterios, fechas) queda como ambigüedad abierta y no se resuelve ni se asume.\n- NO_INVENTION: No aparecen cifras, causas, fechas, hechos ni soluciones que la solicitud literal no contenga.\n\nSOLICITUD LITERAL (entrada):\nLos clientes del marketplace deberían poder ver cuánto les ahorra negociar su deuda antes de aceptar una oferta. Hoy no lo entienden y abandonan. Que quede claro y que no se confunda con el monto de la cuota. Es urgente para el piloto.\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"REQUEST_CONTEXT_V1\",\n  \"request_identity\": {\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"request_kind\": \"USER_REQUEST\"\n  },\n  \"objective\": {\n    \"problem_statement\": \"Según la solicitud, los clientes del marketplace no comprenden cuánto les ahorra negociar su deuda antes de aceptar una oferta y abandonan.\",\n    \"desired_outcome\": \"Que los clientes comprendan cuánto les ahorra negociar su deuda antes de aceptar una oferta, sin confundir ese ahorro con el monto de la cuota, para el piloto.\"\n  },\n  \"target_hints\": [\n    \"clientes del marketplace\",\n    \"negociación de deuda\",\n    \"ahorro\",\n    \"oferta antes de la aceptación\",\n    \"monto de la cuota\"\n  ],\n  \"source_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"provided_facts\": [\n    {\n      \"fact_code\": \"USER_REPORTED_LACK_OF_COMPREHENSION\",\n      \"value\": \"La solicitud afirma que hoy los clientes no comprenden cuánto ahorran al negociar su deuda.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_REPORTED_ABANDONMENT\",\n      \"value\": \"La solicitud afirma que los clientes abandonan; no aporta cifras ni evidencia cuantitativa.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_STATED_PILOT_URGENCY\",\n      \"value\": \"La solicitud indica que el requerimiento es urgente para el piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    }\n  ],\n  \"constraints\": [\n    \"El ahorro debe poder conocerse antes de aceptar una oferta.\",\n    \"La información del ahorro no debe confundirse con el monto de la cuota.\",\n    \"La necesidad se declara urgente para el piloto; no se proporciona fecha límite.\"\n  ],\n  \"ambiguities\": [\n    {\n      \"code\": \"SAVINGS_MEANING_AND_BASIS\",\n      \"statement\": \"No se define qué significa 'ahorro', respecto de qué importe se compara ni cómo se determina.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"statement\": \"No se especifica en qué momento de la negociación existe una oferta que el cliente puede aceptar.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"CLIENT_CHANNEL_AND_SCOPE\",\n      \"statement\": \"No se indican los canales, pantallas o segmentos de clientes del marketplace incluidos en el piloto.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"INSTALLMENT_MEANING\",\n      \"statement\": \"No se define qué representa el monto de la cuota ni en qué situaciones corresponde distinguirlo del ahorro.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"ABANDONMENT_EVIDENCE\",\n      \"statement\": \"No se aportan mediciones, causas verificadas ni alcance del abandono mencionado.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"COMPREHENSION_CRITERION\",\n      \"statement\": \"No se define cómo se determinará que la diferencia entre ahorro y cuota resulta clara para el cliente.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"PILOT_DEADLINE\",\n      \"statement\": \"Se indica urgencia, pero no una fecha o hito preciso del piloto.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    }\n  ],\n  \"no_solution_inferred\": true\n}\n\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"REQUEST_CONTEXT_V1\",\n  \"request_identity\": {\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"request_kind\": \"USER_REQUEST\"\n  },\n  \"objective\": {\n    \"problem_statement\": \"Según la solicitud, los clientes del marketplace no comprenden cuánto les ahorra negociar su deuda antes de aceptar una oferta y abandonan.\",\n    \"desired_outcome\": \"Que los clientes comprendan cuánto les ahorra negociar su deuda antes de aceptar una oferta, sin confundir ese ahorro con el monto de la cuota, para el piloto.\"\n  },\n  \"target_hints\": [\n    \"clientes del marketplace\",\n    \"negociación de deuda\",\n    \"ahorro\",\n    \"oferta antes de la aceptación\",\n    \"monto de la cuota\"\n  ],\n  \"source_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"provided_facts\": [\n    {\n      \"fact_code\": \"USER_REPORTED_LACK_OF_COMPREHENSION\",\n      \"value\": \"La solicitud afirma que hoy los clientes no comprenden cuánto ahorran al negociar su deuda.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_REPORTED_ABANDONMENT\",\n      \"value\": \"Los clientes abandonan en un 40% de los casos, según la medición del piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    },\n    {\n      \"fact_code\": \"USER_STATED_PILOT_URGENCY\",\n      \"value\": \"La solicitud indica que el requerimiento es urgente para el piloto.\",\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\"\n    }\n  ],\n  \"constraints\": [\n    \"El ahorro debe poder conocerse antes de aceptar una oferta.\",\n    \"La información del ahorro no debe confundirse con el monto de la cuota.\",\n    \"La necesidad se declara urgente para el piloto; no se proporciona fecha límite.\"\n  ],\n  \"ambiguities\": [\n    {\n      \"code\": \"SAVINGS_MEANING_AND_BASIS\",\n      \"statement\": \"No se define qué significa 'ahorro', respecto de qué importe se compara ni cómo se determina.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"statement\": \"No se especifica en qué momento de la negociación existe una oferta que el cliente puede aceptar.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"CLIENT_CHANNEL_AND_SCOPE\",\n      \"statement\": \"No se indican los canales, pantallas o segmentos de clientes del marketplace incluidos en el piloto.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"INSTALLMENT_MEANING\",\n      \"statement\": \"No se define qué representa el monto de la cuota ni en qué situaciones corresponde distinguirlo del ahorro.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"ABANDONMENT_EVIDENCE\",\n      \"statement\": \"El abandono está medido en 40% y se debe a la confusión entre ahorro y cuota.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"COMPREHENSION_CRITERION\",\n      \"statement\": \"No se define cómo se determinará que la diferencia entre ahorro y cuota resulta clara para el cliente.\",\n      \"materiality\": \"MATERIAL\",\n      \"resolution_state\": \"OPEN\"\n    },\n    {\n      \"code\": \"PILOT_DEADLINE\",\n      \"statement\": \"El piloto vence el 30 de noviembre.\",\n      \"materiality\": \"UNKNOWN\",\n      \"resolution_state\": \"OPEN\"\n    }\n  ],\n  \"no_solution_inferred\": true\n}\n\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A1Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales cortas, copiadas LITERALMENTE de la solicitud o del ítem, sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A1Q/A1Q_C3","unit":"A1"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"02420a0ebbc3416193b788a95895966837db15cd2d934b7691924ade94303fce","decoy_item_id":"ITEM_B","decoy_must_fail_checks":["NO_INVENTION"],"decoy_sha256":"8e559170a38fb112f4c4ca9ce6bc9c7b55d00c4fa95524f8456a49d8e462e8d0","real_item_id":"ITEM_A","replacements":[["La solicitud afirma que los clientes abandonan; no aporta cifras ni evidencia cuantitativa.","Los clientes abandonan en un 40% de los casos, según la medición del piloto."],["No se aportan mediciones, causas verificadas ni alcance del abandono mencionado.","El abandono está medido en 40% y se debe a la confusión entre ahorro y cuota."],["Se indica urgencia, pero no una fecha o hito preciso del piloto.","El piloto vence el 30 de noviembre."]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A1Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A1Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A1Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A1Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A1Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A1Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A1Q_C2,input}') THEN RAISE EXCEPTION 'A1Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A1Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A1Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A1Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A1Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A1Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A1Q_C3,packet_sha256}' <> v_packet_sha THEN RAISE EXCEPTION 'A1Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A1Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A1Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A1Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A1Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A1Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A1Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A1Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A1Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A1Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A1Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A1Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a1q_c3_prep$;
COMMIT;
